From 2a30d0b53918188a61cb5262c60d41699a58cd37 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:32:14 +0100
Subject: [PATCH] foldermodel: sort names naturally like Dolphin

Folder View compared names with a default QCollator, so file10 sorted
before file2. It now uses numeric, case-insensitive comparison unless
Dolphin is set to case-sensitive or case-insensitive sorting instead.

BUG: 466544
---
 .../desktop/plugins/folder/foldermodel.cpp       | 16 ++++++++++++----
 .../desktop/plugins/folder/foldermodel.h         |  2 ++
 2 files changed, 14 insertions(+), 4 deletions(-)

diff --git a/containments/desktop/plugins/folder/foldermodel.cpp b/containments/desktop/plugins/folder/foldermodel.cpp
index 678bae687c..30d808c7bc 100644
--- a/containments/desktop/plugins/folder/foldermodel.cpp
+++ b/containments/desktop/plugins/folder/foldermodel.cpp
@@ -218,6 +218,16 @@ FolderModel::FolderModel(QObject *parent)
     , m_currentActivity(KActivities::Consumer().currentActivity())
     , m_showHiddenFiles(false)
 {
+    const QString sortingChoice = KConfigGroup(KSharedConfig::openConfig(QStringLiteral("dolphinrc")), QStringLiteral("General")).readEntry("SortingChoice");
+    if (sortingChoice == QLatin1String("CaseSensitiveSorting")) {
+        m_collator.setCaseSensitivity(Qt::CaseSensitive);
+    } else if (sortingChoice == QLatin1String("CaseInsensitiveSorting")) {
+        m_collator.setCaseSensitivity(Qt::CaseInsensitive);
+    } else {
+        m_collator.setNumericMode(true);
+        m_collator.setCaseSensitivity(Qt::CaseInsensitive);
+    }
+
     connect(DragTracker::self(), &DragTracker::dragInProgressChanged, this, &FolderModel::draggingChanged);
     connect(DragTracker::self(), &DragTracker::dragInProgressChanged, this, &FolderModel::dragInProgressAnywhereChanged);
     DirLister *dirLister = new DirLister(this);
@@ -1731,14 +1741,12 @@ bool FolderModel::lessThan(const QModelIndex &left, const QModelIndex &right) co
     if (result != 0)
         return result < 0;

-    QCollator collator;
-
-    result = collator.compare(leftItem.text(), rightItem.text());
+    result = m_collator.compare(leftItem.text(), rightItem.text());

     if (result != 0)
         return result < 0;

-    result = collator.compare(leftItem.name(), rightItem.name());
+    result = m_collator.compare(leftItem.name(), rightItem.name());

     if (result != 0)
         return result < 0;
diff --git a/containments/desktop/plugins/folder/foldermodel.h b/containments/desktop/plugins/folder/foldermodel.h
index c2a2a388f9..9ae4a114d4 100644
--- a/containments/desktop/plugins/folder/foldermodel.h
+++ b/containments/desktop/plugins/folder/foldermodel.h
@@ -9,6 +9,7 @@
 #pragma once

 #include <QAction>
+#include <QCollator>
 #include <QImage>
 #include <QItemSelection>
 #include <QMimeData>
@@ -422,6 +423,7 @@ private:
      */
     QString m_currentActivity;
     bool m_showHiddenFiles;
+    QCollator m_collator;

 #ifdef BUILD_TESTING
     QSizeF m_screenResolution;
